func (o RecurringExpenseSlice) copyMatchingRows(from ...*RecurringExpense) {
	fromByPK := make(map[uuid.UUID]*RecurringExpense, len(from))
	for _, new := range from {
		// keep the first row for each key, like the nested loop did
		if _, ok := fromByPK[new.ID]; !ok {
			fromByPK[new.ID] = new
		}
	}

	for i, old := range o {
		new, ok := fromByPK[old.ID]
		if !ok {
			continue
		}
		new.R = old.R
		o[i] = new
	}
}

