type recurringExpenseJoins[Q dialect.Joinable] struct {
	typ       string
	Category  modAs[Q, categoryColumns]
	Household modAs[Q, householdColumns]
	Account   modAs[Q, accountColumns]
}

func (j recurringExpenseJoins[Q]) aliasedAs(alias string) recurringExpenseJoins[Q] {
	return buildRecurringExpenseJoins[Q](buildRecurringExpenseColumns(alias), j.typ)
}

func buildRecurringExpenseJoins[Q dialect.Joinable](cols recurringExpenseColumns, typ string) recurringExpenseJoins[Q] {
	return recurringExpenseJoins[Q]{
		typ: typ,
		Category: modAs[Q, categoryColumns]{
			c: Categories.Columns,
			f: func(to categoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Categories.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.CategoryID),
					))
				}

				return mods
			},
		},
		Household: modAs[Q, householdColumns]{
			c: Households.Columns,
			f: func(to householdColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Households.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.HouseholdID),
					))
				}

				return mods
			},
		},
		Account: modAs[Q, accountColumns]{
			c: Accounts.Columns,
			f: func(to accountColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Accounts.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PaymentAccountID),
					))
				}

				return mods
			},
		},
	}
}
